require __DIR__.'/../app/bootstrap.php';require_admin();require __DIR__.'/../app/view.php';page_start('Statistiques');admin_nav('analytics.php');heading('MESURE SOBRE','Comprendre les consultations.','Compteurs journaliers des pages de veille, sans adresse IP ni identifiant visiteur dans les statistiques.');
$stats=run('SELECT day,SUM(count) AS total FROM visits GROUP BY day ORDER BY day DESC LIMIT 30')->fetchAll();$max=max(1,...array_column($stats,'total'));
?><section class="panel"><h2>Consultations des 30 derniers jours disponibles</h2><p>Une consultation correspond à une ouverture ou un rechargement d’une page Actualités, Vulnérabilités ou Favoris. Ces chiffres ne mesurent pas des visiteurs uniques et peuvent inclure des robots.</p><?php if(!$stats):?><p>Aucune consultation enregistrée.</p><?php endif ?><div class="chart"><?php foreach($stats as $s):?><div class="chart-row"><span><?=e($s['day'])?></span><meter min="0" max="<?=$max?>" value="<?=$s['total']?>"><?=$s['total']?></meter><strong><?=$s['total']?></strong></div><?php endforeach ?></div></section><section class="panel"><h2>Répartition par page — 30 jours</h2><table><thead><tr><th>Page</th><th>Consultations</th></tr></thead><tbody><?php foreach(run('SELECT page,SUM(count) AS total FROM visits WHERE day>=? GROUP BY page',[date('Y-m-d',time()-29*86400)])->fetchAll() as $s):?><tr><td><?=e($s['page'])?></td><td><?=$s['total']?></td></tr><?php endforeach ?></tbody></table><p class="muted">Conservation des compteurs : 90 jours. Aucun journal historique de l’ancienne version n’est importé.</p></section><?php page_end();
